commit d471022b2772071877895759f209f2c346757a4c
Author: Christos Zoulas <christos@zoulas.com>
Date:   Tue Jul 5 19:53:42 2022 +0000

    Use printf("%lc") instead of putwc(). Somehow mixing wide and narrow stdio
    does not work on Linux?

diff --git a/src/file.c b/src/file.c
index 8b4f14c2..6ad3a0f8 100644
--- a/src/file.c
+++ b/src/file.c
@@ -32,7 +32,7 @@
 #include "file.h"

 #ifndef        lint
-FILE_RCSID("@(#)$File: file.c,v 1.199 2022/07/04 22:30:51 christos Exp $")
+FILE_RCSID("@(#)$File: file.c,v 1.200 2022/07/05 19:53:42 christos Exp $")
 #endif /* lint */

 #include "magic.h"
@@ -589,7 +589,7 @@ fname_print(const char *inname)
                inname += bytesconsumed;
                n -= bytesconsumed;
                if (iswprint(nextchar)) {
-                       putwc(nextchar, stdout);
+                       printf("%lc", nextchar);
                        continue;
                }
                /* XXX: What if it is > 255? */
